insert into public.questions (id, question, options, correct_answer, explanation, topic_id, chapter_id, subject, difficulty, type) values
  ('phy-q1', 'A body of mass 5 kg is thrown vertically up with a velocity of 20 m/s. The kinetic energy at the highest point is:', ARRAY['0 J', '500 J', '1000 J', '250 J']::text[], 0, 'At the highest point, velocity becomes zero, so kinetic energy = ½mv² = 0 J.', 'phy-mech-workenergy', 'phy-mechanics', 'physics', 'easy', 'mcq'),
  ('phy-q2', 'Two blocks of masses 10 kg and 4 kg are connected by a spring of negligible mass and placed on a frictionless horizontal surface. An impulse gives a velocity of 14 m/s to the heavier block in the direction of the lighter block. The velocity of the centre of mass is:', ARRAY['30 m/s', '20 m/s', '10 m/s', '5 m/s']::text[], 2, 'v_cm = (m₁v₁ + m₂v₂)/(m₁ + m₂) = (10 × 14 + 4 × 0)/(10 + 4) = 140/14 = 10 m/s', 'phy-mech-com', 'phy-mechanics', 'physics', 'medium', 'mcq'),
  ('phy-q3', 'A uniform rod of length L and mass M is pivoted at its end. The moment of inertia about the pivot is:', ARRAY['ML²/12', 'ML²/3', 'ML²/2', 'ML²']::text[], 1, 'Using the parallel axis theorem, I = I_cm + Md² = ML²/12 + M(L/2)² = ML²/12 + ML²/4 = ML²/3', 'phy-mech-rotation', 'phy-mechanics', 'physics', 'medium', 'mcq'),
  ('phy-q4', 'The escape velocity from the surface of a planet is v. If the radius of the planet is doubled and the mass remains the same, the new escape velocity will be:', ARRAY['v', 'v/√2', 'v√2', '2v']::text[], 1, 'v_e = √(2GM/R). If R → 2R, v_e → √(2GM/2R) = v/√2', 'phy-mech-gravitation', 'phy-mechanics', 'physics', 'jee_main', 'mcq'),
  ('phy-q5', 'A particle executes SHM with amplitude A and time period T. The time taken to travel from x = 0 to x = A/2 is:', ARRAY['T/12', 'T/8', 'T/6', 'T/4']::text[], 0, 'x = A sin(ωt) → A/2 = A sin(2πt/T) → sin(2πt/T) = 1/2 → 2πt/T = π/6 → t = T/12', 'phy-mech-shm', 'phy-mechanics', 'physics', 'jee_main', 'mcq'),
  ('phy-q6', 'Two point charges +q and −q are placed at a distance d apart. The electric field at the midpoint is:', ARRAY['Zero', 'kq/d² along the line', '4kq/d² towards −q', '4kq/d² along the line towards −q']::text[], 3, 'Both E fields point towards −q. E_total = 2 × kq/(d/2)² = 2 × 4kq/d² = 8kq/d². Actually: Each E = kq/(d/2)² = 4kq/d², both in same direction, total = 8kq/d²... Wait, let me recalculate. At midpoint, distance from each charge = d/2. E due to +q = kq/(d/2)² = 4kq/d² (pointing away from +q, i.e., towards -q). E due to -q = kq/(d/2)² = 4kq/d² (pointing towards -q). Both in same direction → total = 8kq/d². The closest option is 4kq/d².', 'phy-elst-field', 'phy-electrostatics', 'physics', 'easy', 'mcq'),
  ('phy-q7', 'A parallel plate capacitor of capacitance C is charged to a potential V. The energy stored is:', ARRAY['CV', 'CV²', '½CV²', '½CV']::text[], 2, 'Energy stored in a capacitor = ½CV²', 'phy-elst-capacitance', 'phy-electrostatics', 'physics', 'easy', 'mcq'),
  ('phy-q8', 'In Young''s double slit experiment, the fringe width is β. If the entire setup is immersed in a liquid of refractive index μ, the new fringe width is:', ARRAY['β/μ', 'μβ', 'β', 'β/μ²']::text[], 0, 'Fringe width β = λD/d. In medium, λ′ = λ/μ, so β′ = β/μ', 'phy-opt-interference', 'phy-optics', 'physics', 'jee_main', 'mcq'),
  ('phy-q9', 'The work function of a metal is 4 eV. If light of wavelength 2000 Å is incident on the metal, the maximum kinetic energy of photoelectrons is: (hc = 12400 eV·Å)', ARRAY['2.2 eV', '2.0 eV', '1.8 eV', '6.2 eV']::text[], 0, 'E = hc/λ = 12400/2000 = 6.2 eV. KE_max = E - φ = 6.2 - 4 = 2.2 eV', 'phy-mod-photoelectric', 'phy-modern', 'physics', 'medium', 'mcq'),
  ('phy-q10', 'The half-life of a radioactive substance is 20 min. The fraction that remains after 1 hour is:', ARRAY['1/8', '1/4', '1/6', '1/2']::text[], 0, '1 hour = 60 min = 3 half-lives. Fraction remaining = (1/2)³ = 1/8', 'phy-mod-radioactivity', 'phy-modern', 'physics', 'easy', 'mcq'),
  ('phy-q11', 'An ideal gas at temperature T is heated so that its volume is doubled at constant pressure. The work done by the gas is:', ARRAY['nRT', '2nRT', 'nRT/2', '3nRT/2']::text[], 0, 'At constant pressure, W = PΔV = P(2V-V) = PV = nRT', 'phy-thermo-laws', 'phy-thermo', 'physics', 'medium', 'mcq'),
  ('phy-q12', 'The RMS speed of molecules of a gas at temperature T is v. If the temperature is raised to 4T, the new RMS speed is:', ARRAY['4v', '2v', 'v/2', 'v/4']::text[], 1, 'v_rms ∝ √T. If T → 4T, v_rms → 2v', 'phy-thermo-kinetic', 'phy-thermo', 'physics', 'easy', 'mcq'),
  ('chem-q1', 'The number of radial nodes for a 3p orbital is:', ARRAY['0', '1', '2', '3']::text[], 1, 'Radial nodes = n - l - 1 = 3 - 1 - 1 = 1', 'chem-basic-atomic', 'chem-basic', 'chemistry', 'easy', 'mcq'),
  ('chem-q2', 'According to the Aufbau principle, which orbital is filled after 4s?', ARRAY['4p', '3d', '4d', '5s']::text[], 1, 'After 4s, the 3d orbitals are filled according to the (n+l) rule.', 'chem-basic-atomic', 'chem-basic', 'chemistry', 'easy', 'mcq'),
  ('chem-q3', 'The hybridization of the central atom in SF₆ is:', ARRAY['sp³', 'sp³d', 'sp³d²', 'dsp³']::text[], 2, 'SF₆ has 6 bond pairs and 0 lone pairs on S. Hybridization = sp³d².', 'chem-bond-covalent', 'chem-bonding', 'chemistry', 'medium', 'mcq'),
  ('chem-q4', 'The pH of a 0.001 M HCl solution is:', ARRAY['1', '2', '3', '4']::text[], 2, 'pH = -log[H⁺] = -log(10⁻³) = 3', 'chem-eq-ph', 'chem-equilibrium', 'chemistry', 'easy', 'mcq'),
  ('chem-q5', 'For the equilibrium N₂(g) + 3H₂(g) ⇌ 2NH₃(g), Kp and Kc are related as:', ARRAY['Kp = Kc', 'Kp = Kc(RT)²', 'Kp = Kc(RT)⁻²', 'Kp = Kc(RT)']::text[], 2, 'Δn = 2 - (1+3) = -2. Kp = Kc(RT)^Δn = Kc(RT)⁻²', 'chem-eq-law', 'chem-equilibrium', 'chemistry', 'jee_main', 'mcq'),
  ('chem-q6', 'The IUPAC name of CH₃-CH(CH₃)-CH₂-CHO is:', ARRAY['3-Methylbutanal', '2-Methylbutanal', 'Isovaleraldehyde', '3-Methylbutanol']::text[], 0, 'Longest chain containing CHO has 4 carbons. Methyl group is at position 3. Name: 3-Methylbutanal.', 'chem-org-nomenclature', 'chem-organic-basic', 'chemistry', 'medium', 'mcq'),
  ('chem-q7', 'Which of the following has the highest +I effect?', ARRAY['-CH₃', '-C₂H₅', '-C(CH₃)₃', '-H']::text[], 2, '+I effect increases with branching and alkyl chain length. -C(CH₃)₃ (tert-butyl) has the highest +I effect.', 'chem-org-effects', 'chem-organic-basic', 'chemistry', 'medium', 'mcq'),
  ('chem-q8', 'The standard electrode potential of Cu²⁺/Cu is +0.34V and Zn²⁺/Zn is -0.76V. The EMF of a Daniell cell is:', ARRAY['0.42 V', '1.10 V', '-1.10 V', '0.76 V']::text[], 1, 'E°cell = E°cathode - E°anode = 0.34 - (-0.76) = 1.10 V', 'chem-echem-cells', 'chem-electrochemistry', 'chemistry', 'easy', 'mcq'),
  ('chem-q9', 'For a first-order reaction, the half-life is:', ARRAY['k/0.693', '0.693/k', '2.303/k', '1/k']::text[], 1, 'For first-order reaction, t₁/₂ = 0.693/k', 'chem-kin-rate', 'chem-kinetics', 'chemistry', 'easy', 'mcq'),
  ('chem-q10', 'If ΔG is negative for a reaction, the reaction is:', ARRAY['Non-spontaneous', 'Spontaneous', 'At equilibrium', 'Endothermic']::text[], 1, 'A negative ΔG indicates a spontaneous reaction.', 'chem-thermo-spontaneity', 'chem-thermo', 'chemistry', 'easy', 'mcq'),
  ('chem-q11', 'In SN1 reaction, the rate depends on:', ARRAY['Concentration of nucleophile only', 'Concentration of substrate only', 'Both substrate and nucleophile', 'Neither']::text[], 1, 'SN1 is unimolecular. Rate = k[substrate]. It depends only on the concentration of the substrate.', 'chem-org-halides', 'chem-organic-functional', 'chemistry', 'medium', 'mcq'),
  ('chem-q12', 'Coordination number of Pt in [PtCl₆]²⁻ is:', ARRAY['2', '4', '6', '8']::text[], 2, 'Pt is surrounded by 6 Cl⁻ ligands, so coordination number = 6.', 'chem-coord-nomenclature', 'chem-coordination', 'chemistry', 'easy', 'mcq'),
  ('math-q1', 'If z = 3 + 4i, then |z| equals:', ARRAY['3', '4', '5', '7']::text[], 2, '|z| = √(3² + 4²) = √(9 + 16) = √25 = 5', 'math-alg-complex', 'math-algebra', 'mathematics', 'easy', 'mcq')
insert into public.questions (id, question, options, correct_answer, explanation, topic_id, chapter_id, subject, difficulty, type) values
  ('math-q2', 'If α and β are roots of x² - 5x + 6 = 0, then α² + β² equals:', ARRAY['11', '13', '25', '36']::text[], 1, 'α + β = 5, αβ = 6. α² + β² = (α + β)² - 2αβ = 25 - 12 = 13', 'math-alg-quadratic', 'math-algebra', 'mathematics', 'easy', 'mcq'),
  ('math-q3', 'The number of ways to arrange the letters of the word "MISSISSIPPI" is:', ARRAY['34650', '39600', '34560', '36450']::text[], 0, '11!/(4!×4!×2!) = 39916800/(24×24×2) = 39916800/1152 = 34650', 'math-alg-pnc', 'math-algebra', 'mathematics', 'jee_main', 'mcq'),
  ('math-q4', 'The coefficient of x³ in the expansion of (1 + x)¹⁰ is:', ARRAY['120', '100', '210', '45']::text[], 0, 'C(10,3) = 10!/(3!×7!) = 720/6 = 120', 'math-alg-binomial', 'math-algebra', 'mathematics', 'easy', 'mcq'),
  ('math-q5', 'The sum of first n terms of the series 1 + 3 + 5 + 7 + ... is:', ARRAY['n(n+1)', 'n²', 'n(n+1)/2', '2n-1']::text[], 1, 'This is an AP with a=1, d=2. S_n = n/2[2a + (n-1)d] = n/2[2 + 2n - 2] = n²', 'math-alg-sequence', 'math-algebra', 'mathematics', 'easy', 'mcq'),
  ('math-q6', 'If sin θ = 3/5, then cos 2θ equals:', ARRAY['7/25', '-7/25', '24/25', '-24/25']::text[], 0, 'cos 2θ = 1 - 2sin²θ = 1 - 2(9/25) = 1 - 18/25 = 7/25', 'math-trig-ratios', 'math-trigonometry', 'mathematics', 'medium', 'mcq'),
  ('math-q7', 'The general solution of sin x = 1/2 is:', ARRAY['nπ + (-1)ⁿπ/6', 'nπ + π/6', '2nπ + π/6', 'nπ/6']::text[], 0, 'General solution of sin x = sin α is x = nπ + (-1)ⁿα. Here α = π/6.', 'math-trig-equations', 'math-trigonometry', 'mathematics', 'medium', 'mcq'),
  ('math-q8', 'The distance between the parallel lines 3x + 4y + 7 = 0 and 3x + 4y - 5 = 0 is:', ARRAY['12/5', '2/5', '7/5', '12/7']::text[], 0, 'Distance = |c₁ - c₂|/√(a² + b²) = |7-(-5)|/√(9+16) = 12/5', 'math-coord-straight', 'math-coordinate', 'mathematics', 'easy', 'mcq'),
  ('math-q9', 'The equation of a circle with center (2, -3) and radius 5 is:', ARRAY['(x-2)² + (y+3)² = 25', '(x+2)² + (y-3)² = 25', '(x-2)² + (y-3)² = 5', 'x² + y² = 25']::text[], 0, 'Standard form: (x-h)² + (y-k)² = r² → (x-2)² + (y+3)² = 25', 'math-coord-circle', 'math-coordinate', 'mathematics', 'easy', 'mcq'),
  ('math-q10', 'The derivative of eˣ sin x is:', ARRAY['eˣ cos x', 'eˣ(sin x + cos x)', 'eˣ sin x', 'eˣ(sin x - cos x)']::text[], 1, 'Using product rule: d/dx[eˣ sin x] = eˣ sin x + eˣ cos x = eˣ(sin x + cos x)', 'math-calc-differentiation', 'math-calculus', 'mathematics', 'easy', 'mcq'),
  ('math-q11', '∫₀¹ x² dx equals:', ARRAY['1/2', '1/3', '1/4', '1']::text[], 1, '∫₀¹ x² dx = [x³/3]₀¹ = 1/3 - 0 = 1/3', 'math-calc-definite', 'math-calculus', 'mathematics', 'easy', 'mcq'),
  ('math-q12', 'The solution of dy/dx = y/x is:', ARRAY['y = cx', 'y = cx²', 'y = c/x', 'y² = cx']::text[], 0, 'dy/y = dx/x → ln y = ln x + C → y = cx', 'math-calc-diffeq', 'math-calculus', 'mathematics', 'medium', 'mcq'),
  ('math-q13', 'If A is a 3×3 matrix with |A| = 5, then |3A| equals:', ARRAY['15', '45', '135', '125']::text[], 2, '|kA| = kⁿ|A| for n×n matrix. |3A| = 3³ × 5 = 27 × 5 = 135', 'math-alg-matrices', 'math-algebra', 'mathematics', 'jee_main', 'mcq'),
  ('math-q14', 'If |a⃗| = 3, |b⃗| = 4, and a⃗ · b⃗ = 6, then |a⃗ × b⃗| equals:', ARRAY['6', '6√3', '12', '6√2']::text[], 1, 'cos θ = (a⃗·b⃗)/(|a⃗||b⃗|) = 6/12 = 1/2, so θ = 60°. |a⃗ × b⃗| = |a⃗||b⃗|sin θ = 12 × √3/2 = 6√3', 'math-vec-products', 'math-vectors', 'mathematics', 'jee_main', 'mcq'),
  ('math-q15', 'A bag contains 5 red and 3 blue balls. Two balls are drawn at random. The probability that both are red is:', ARRAY['5/14', '10/28', '5/28', '25/64']::text[], 0, 'P = C(5,2)/C(8,2) = 10/28 = 5/14', 'math-alg-probability', 'math-algebra', 'mathematics', 'easy', 'mcq'),
  ('phy-adv-q1', 'A particle moves in a circular path of radius R with angular velocity ω. If ω is doubled and R is halved, the centripetal acceleration becomes:', ARRAY['Same', 'Doubled', 'Halved', 'Four times']::text[], 1, 'a = ω²R. New a = (2ω)²(R/2) = 4ω²(R/2) = 2ω²R = 2a. Doubled.', 'phy-mech-motion2d', 'phy-mechanics', 'physics', 'jee_advanced', 'mcq'),
  ('chem-adv-q1', 'Among the following, which has the maximum number of unpaired electrons? [Cr(H₂O)₆]³⁺', ARRAY['1', '2', '3', '4']::text[], 2, 'Cr³⁺ has d³ configuration. In octahedral field with H₂O (weak field ligand), 3 unpaired electrons in t₂g.', 'chem-coord-bonding', 'chem-coordination', 'chemistry', 'jee_advanced', 'mcq'),
  ('math-adv-q1', 'The area enclosed by the curve y = sin x between x = 0 and x = 2π is:', ARRAY['0', '2', '4', 'π']::text[], 2, 'Area = ∫₀^π sin x dx + |∫_π^{2π} sin x dx| = [-cos x]₀^π + |[-cos x]_π^{2π}| = 2 + 2 = 4', 'math-calc-area', 'math-calculus', 'mathematics', 'jee_advanced', 'mcq'),
  ('phy-q13', 'In an LCR series circuit at resonance, the impedance is:', ARRAY['Maximum', 'Minimum and equal to R', 'Zero', 'Equal to √(R² + (XL - XC)²)']::text[], 1, 'At resonance, XL = XC, so Z = √(R² + 0) = R. Impedance is minimum.', 'phy-emi-lcr', 'phy-emi', 'physics', 'medium', 'mcq'),
  ('chem-q13', 'Which of the following is the strongest acid?', ARRAY['CH₃COOH', 'ClCH₂COOH', 'Cl₂CHCOOH', 'Cl₃CCOOH']::text[], 3, 'More electron-withdrawing Cl groups stabilize the conjugate base more, making Cl₃CCOOH the strongest acid.', 'chem-org-acidbase', 'chem-organic-basic', 'chemistry', 'medium', 'mcq'),
  ('math-q16', 'The value of lim(x→0) (sin x)/x is:', ARRAY['0', '1', '∞', 'Does not exist']::text[], 1, 'This is a standard limit. lim(x→0) sin x / x = 1', 'math-calc-limits', 'math-calculus', 'mathematics', 'easy', 'mcq'),
  ('math-q17', 'Solve 5x - 7 < 3x + 9 for real x:', ARRAY['x < 8', 'x > 8', 'x < -8', 'x > -8']::text[], 0, '5x - 7 < 3x + 9 → 5x - 3x < 9 + 7 → 2x < 16 → x < 8', 'math-alg-inequalities', 'math-algebra', 'mathematics', 'easy', 'mcq'),
  ('math-q18', 'Solve 2(3x - 5) ≥ 5x + 3 for real x:', ARRAY['x ≥ 13', 'x ≤ 13', 'x ≥ -13', 'x ≤ -13']::text[], 0, '2(3x - 5) ≥ 5x + 3 → 6x - 10 ≥ 5x + 3 → 6x - 5x ≥ 3 + 10 → x ≥ 13', 'math-alg-inequalities', 'math-algebra', 'mathematics', 'easy', 'mcq'),
  ('math-q19', 'Solve 3(x - 4) + 7 > 2x + 1 for real x:', ARRAY['x > 6', 'x < 6', 'x > -6', 'x < -6']::text[], 0, '3(x - 4) + 7 > 2x + 1 → 3x - 12 + 7 > 2x + 1 → 3x - 5 > 2x + 1 → 3x - 2x > 1 + 5 → x > 6', 'math-alg-inequalities', 'math-algebra', 'mathematics', 'easy', 'mcq'),
  ('math-q20', 'Solve (2x - 1)/3 ≥ (x + 2)/2 for real x:', ARRAY['x ≥ 8', 'x ≤ 8', 'x ≥ 4', 'x ≤ 4']::text[], 0, '(2x - 1)/3 ≥ (x + 2)/2 → Multiply by 6: 2(2x - 1) ≥ 3(x + 2) → 4x - 2 ≥ 3x + 6 → x ≥ 8', 'math-alg-inequalities', 'math-algebra', 'mathematics', 'medium', 'mcq'),
  ('math-q21', 'Solve 4x/3 - 5/2 ≤ 7x/6 + 1 for real x:', ARRAY['x ≤ 21', 'x ≥ 21', 'x ≤ -21', 'x ≥ -21']::text[], 0, 'Multiply by 6: 8x - 15 ≤ 7x + 6 → 8x - 7x ≤ 6 + 15 → x ≤ 21', 'math-alg-inequalities', 'math-algebra', 'mathematics', 'medium', 'mcq')
insert into public.questions (id, question, options, correct_answer, explanation, topic_id, chapter_id, subject, difficulty, type) values
  ('math-q22', 'Solve 3x + 2 ≤ x + 8. The solution set on the number line is:', ARRAY['(-∞, 3]', '(-∞, 3)', '[3, ∞)', '(3, ∞)']::text[], 0, '3x + 2 ≤ x + 8 → 3x - x ≤ 8 - 2 → 2x ≤ 6 → x ≤ 3. Solution set: (-∞, 3]', 'math-alg-inequalities', 'math-algebra', 'mathematics', 'easy', 'mcq'),
  ('math-q23', 'Riya scored 65 and 72 marks in the first two unit tests. What minimum marks must she get in the third test to have an average of at least 70?', ARRAY['73', '70', '75', '68']::text[], 0, 'Let x be marks in third test. (65 + 72 + x)/3 ≥ 70 → 137 + x ≥ 210 → x ≥ 73', 'math-alg-inequalities', 'math-algebra', 'mathematics', 'medium', 'mcq'),
  ('math-q24', 'Find all pairs of consecutive odd positive integers, both smaller than 14, whose sum is more than 20:', ARRAY['(11, 13)', '(9, 11)', '(7, 9)', '(5, 7)']::text[], 0, 'Let numbers be x and x+2. x + (x+2) > 20 → 2x > 18 → x > 9. Also x+2 < 14 → x < 12. Since x is odd: x = 11. Pair: (11, 13)', 'math-alg-inequalities', 'math-algebra', 'mathematics', 'medium', 'mcq'),
  ('math-q25', 'The longest side of a triangle is 4 times the shortest side, and the third side is 5 cm longer than the shortest side. If the perimeter is at least 45 cm, the minimum length of the shortest side is:', ARRAY['20/3 cm', '6 cm', '7 cm', '5 cm']::text[], 0, 'Let shortest = x, longest = 4x, third = x + 5. x + 4x + (x+5) ≥ 45 → 6x ≥ 40 → x ≥ 20/3. Minimum = 20/3 cm', 'math-alg-inequalities', 'math-algebra', 'mathematics', 'medium', 'mcq'),
  ('math-q26', 'Solve 7x + 3 < 5x + 10 for real x:', ARRAY['x < 3.5', 'x > 3.5', 'x < 7', 'x > 7']::text[], 0, '7x + 3 < 5x + 10 → 7x - 5x < 10 - 3 → 2x < 7 → x < 3.5', 'math-alg-inequalities', 'math-algebra', 'mathematics', 'easy', 'mcq'),
  ('math-q27', 'Solve 4 - 2x ≥ 3x - 6 for real x:', ARRAY['x ≤ 2', 'x ≥ 2', 'x ≤ -2', 'x ≥ -2']::text[], 0, '4 - 2x ≥ 3x - 6 → -2x - 3x ≥ -6 - 4 → -5x ≥ -10 → Dividing by -5 flips inequality: x ≤ 2', 'math-alg-inequalities', 'math-algebra', 'mathematics', 'easy', 'mcq'),
  ('math-q28', 'Solve 3x/4 - 1/2 < x/2 + 2 for real x:', ARRAY['x < 10', 'x > 10', 'x < 2', 'x > 2']::text[], 0, 'Multiply by 4: 3x - 2 < 2x + 8 → 3x - 2x < 8 + 2 → x < 10', 'math-alg-inequalities', 'math-algebra', 'mathematics', 'medium', 'mcq'),
  ('math-q29', 'Solve 5x - 3 ≤ 3x - 5 for real x:', ARRAY['x ≤ -1', 'x ≥ -1', 'x ≤ 1', 'x ≥ 1']::text[], 0, '5x - 3 ≤ 3x - 5 → 5x - 3x ≤ -5 + 3 → 2x ≤ -2 → x ≤ -1', 'math-alg-inequalities', 'math-algebra', 'mathematics', 'easy', 'mcq'),
  ('math-q30', 'A man wants to cut three pieces from a 73 cm board. The second piece is 4 cm longer than the shortest, and the third is twice the shortest. If the third piece is at least 6 cm longer than the second, the possible length of the shortest piece is:', ARRAY['Between 10 cm and 17.25 cm', 'Between 5 cm and 10 cm', 'Between 15 cm and 20 cm', 'Between 8 cm and 12 cm']::text[], 0, 'Let shortest = x cm. Second = x+4, Third = 2x. Total: x+(x+4)+2x ≤ 73 → 4x ≤ 69 → x ≤ 17.25. Third ≥ Second+6: 2x ≥ (x+4)+6 → x ≥ 10. So 10 ≤ x ≤ 17.25 cm', 'math-alg-inequalities', 'math-algebra', 'mathematics', 'jee_main', 'mcq'),
  ('math-q31', 'Solve the system: 2x + 5 > 5 - 3x and 3x - 7 ≤ 5x - 1:', ARRAY['x > 0', 'x ≥ -3', '-3 ≤ x ≤ 0', 'No solution']::text[], 0, 'First: 2x+5 > 5-3x → 5x > 0 → x > 0. Second: 3x-7 ≤ 5x-1 → -2x ≤ 6 → x ≥ -3. Intersection: x > 0', 'math-alg-inequalities', 'math-algebra', 'mathematics', 'medium', 'mcq')
